function fmt(n){ return n.toLocaleString("en-US") + " FCFA"; }
function loc(val){ return (val && typeof val === "object") ? (val[currentLang] || val.en) : val; }

function renderSlider(images, prodId){
  if(!images || images.length === 0) return "";
  if(images.length === 1){
    return `<img src="${images[0]}" alt="" loading="lazy" decoding="async">`;
  }
  const imgsHtml = images.map(src => `<img src="${src}" alt="" loading="lazy" decoding="async">`).join("");
  const dotsHtml = images.map((_, i) => `<span class="dot${i===0?" active":""}" onclick="event.stopPropagation(); goToSlide('${prodId}',${i})"></span>`).join("");
  return `
    <div class="img-slider" id="slider-${prodId}" data-index="0" data-count="${images.length}"
         ontouchstart="sliderTouchStart(event,'${prodId}')" ontouchmove="sliderTouchMove(event)" ontouchend="sliderTouchEnd(event,'${prodId}')">
      <div class="slider-track" id="track-${prodId}">${imgsHtml}</div>
      <button class="slider-arrow left" onclick="event.stopPropagation(); moveSlide('${prodId}',-1)">&lsaquo;</button>
      <button class="slider-arrow right" onclick="event.stopPropagation(); moveSlide('${prodId}',1)">&rsaquo;</button>
      <div class="slider-dots">${dotsHtml}</div>
    </div>
  `;
}

function moveSlide(prodId, dir){
  const container = document.getElementById("slider-" + prodId);
  if(!container) return;
  const count = parseInt(container.getAttribute("data-count"), 10);
  let idx = parseInt(container.getAttribute("data-index"), 10);
  idx = (idx + dir + count) % count;
  applySlide(prodId, idx);
}
function goToSlide(prodId, idx){
  applySlide(prodId, idx);
}
function applySlide(prodId, idx){
  const container = document.getElementById("slider-" + prodId);
  const track = document.getElementById("track-" + prodId);
  if(!container || !track) return;
  container.setAttribute("data-index", idx);
  track.style.transform = `translateX(-${idx * 100}%)`;
  container.querySelectorAll(".dot").forEach((d, i) => d.classList.toggle("active", i === idx));
}

let sliderTouchStartX = 0;
function sliderTouchStart(e, prodId){ sliderTouchStartX = e.touches[0].clientX; }
function sliderTouchMove(e){ /* allow vertical scroll, only track horizontal */ }
function sliderTouchEnd(e, prodId){
  const dx = e.changedTouches[0].clientX - sliderTouchStartX;
  if(Math.abs(dx) > 40){ moveSlide(prodId, dx < 0 ? 1 : -1); }
}
function t(key){ return I18N[currentLang][key] || key; }

function setView(v){
  ["home","importation","masterclass","products","admin"].forEach(id=>{
    document.getElementById("view-"+id).classList.toggle("hidden", id!==v);
  });
  document.querySelectorAll(".bottombar button").forEach(b=>{
    b.classList.toggle("active", b.dataset.tab===v || (v==="admin" && b.dataset.tab==="importation"));
  });
  if(v==="importation") renderImportation();
  if(v==="products"){ renderReadyProducts(); renderNewArrivals(); }
  if(v==="admin") renderAdminTable();
  window.scrollTo(0,0);
  window.dispatchEvent(new CustomEvent("ja:view-changed", { detail: { view: v } }));
}

