function handleAdminBtnClick(){
  if(isAdmin){
    logoutAdmin();
  } else {
    document.getElementById("loginModal").classList.add("show");
    document.getElementById("loginPassword").value = "";
    document.getElementById("loginError").classList.add("hidden");
    setTimeout(()=>document.getElementById("loginPassword").focus(), 50);
  }
}
function closeLoginModal(){
  document.getElementById("loginModal").classList.remove("show");
}
function submitLogin(){
  const val = document.getElementById("loginPassword").value;
  if(val === STAFF_PASSWORD){
    isAdmin = true;
    document.getElementById("adminBtn").classList.add("active");
    document.getElementById("adminBtnText").textContent = currentLang==="fr" ? "Vue Admin" : "Admin View";
    closeLoginModal();
    setView("admin");
  } else {
    document.getElementById("loginError").classList.remove("hidden");
  }
}
function logoutAdmin(){
  isAdmin = false;
  document.getElementById("adminBtn").classList.remove("active");
  document.getElementById("adminBtnText").textContent = "Login";
  setView("home");
}

